def finding(item, ordinal, refs):
    fid, name, primary = item
    low = name.lower()
    kinds = [primary if primary in KINDS else "other", KINDS[(ordinal + 8) % len(KINDS)], KINDS[(ordinal + 16) % len(KINDS)]]
    return {"id": fid, "name": name,
        "description": f"Records {low} as source-qualified Audit / Assurance Engagement context while client, subject matter, criteria, statements, disclosures, controls, risks, issues, actions, regulator cases and records masters remain external.",
        "source_refs": refs,
        "questions": [
            {"id": f"{fid}-q01", "text": f"Which stable engagement, version, kind, mandate, subject, criteria, scope, period and external-master identities establish {low}?", "kind": kinds[0], "answer_data": ["engagement, version, appointment, engagement letter, subject, criteria, scope, period and master-system identifiers", "audit, review, assurance, agreed-upon procedures, internal, statutory, performance, compliance and sustainability classes", "proposed, accepted, planned, active, reviewed, completed, reported, archived, withdrawn and superseded states"]},
            {"id": f"{fid}-q02", "text": f"Who appoints, prepares, performs, supervises, reviews, evaluates, concludes, communicates or may rely on {low}, under what ethics and authority?", "kind": kinds[1], "answer_data": ["appointing party, responsible party, measurer or evaluator, practitioner, partner, team, expert, reviewer, governance body and intended user", "mandate, professional standard, law, engagement terms, independence, competence, authorization, access and segregation of duties", "purpose, responsibility, confidentiality, restriction, limitation, exception, escalation and contestability"]},
            {"id": f"{fid}-q03", "text": f"Which assertion, criterion, risk, procedure, evidence, materiality, source, event time, knowledge time, uncertainty and successor lineage qualify {low}?", "kind": kinds[2], "answer_data": ["subject-matter information, assertion, criterion, benchmark, materiality, risk, control, procedure, finding, conclusion and opinion", "evidence source, relevance, reliability, sufficiency, appropriateness, contradiction, limitation, representation and review", "period, procedure, review, report, issuance, observation, ingestion and knowledge times, predecessor, successor, retention and mapping loss"]}],
        "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed engagement data for {low}, qualified by source, criteria, authority, risk, materiality, procedure, evidence, time, access and provenance.", "value_kind": "object", "cardinality": "1", "required": True, "source_refs": refs}],
        "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or versioned evidence for {low} with engagement identity, digest, source, professional-standard version, event and knowledge times, access marking and successor lineage.", "media_or_form": ["application/yaml", "application/json", "application/pdf", "text/csv", "text/markdown", "text/html"], "serial": True, "identity_strategy": "Prefer the authoritative firm, practitioner, client, regulator, repository or records identifier; otherwise use a governed IRI, then a Dimension UUID or ULID.", "source_refs": refs}], "inline_only_rationale": None}


def structure():
    bundles, ordinal = [], 0
    for bid, bname, rationale, layer_rows in ROWS:
        layers, bundle_refs = [], []
        for lid, lname, refs, items in layer_rows:
            bundle_refs.extend(refs)
            findings = []
            for item in items:
                ordinal += 1
                findings.append(finding(item, ordinal, refs))
            layers.append({"id": lid, "name": lname, "description": f"Groups governed assertions about {lname.lower()} for the engagement.", "source_refs": refs, "findings": findings})
        bundles.append({"id": bid, "name": bname, "description": rationale, "rationale": rationale, "source_refs": list(dict.fromkeys(bundle_refs)), "layers": layers})
    return {"bundles": bundles}


